import React, { useState, useEffect, useMemo } from 'react';
import { Header, Footer } from './components/common/Layout';
import { LoginScreen } from './components/screens/LoginScreen';
import { baseStyles, globalStyles } from './styles/global';
import { SKILLS, getSkillsFor } from './data/skills';
import { GRADES } from './data/grades';
import { SUBJECTS } from './data/subjects';
import { BADGES } from './data/badges';
import { calcMastery } from './utils/helpers';

// Note: This is a simplified example. Implement remaining screens in separate component files
// See PROJECT_STRUCTURE.md for detailed organization

export default function App() {
  const [view, setView] = useState('login');
  const [user, setUser] = useState(null);
  const [selectedGrade, setSelectedGrade] = useState(null);
  const [selectedSubject, setSelectedSubject] = useState(null);
  const [activeSkill, setActiveSkill] = useState(null);
  const [progress, setProgress] = useState({});
  const [stats, setStats] = useState({
    points: 0,
    streak: 1,
    bestStreak: 0,
    currentRunStreak: 0,
    totalAnswered: 0,
    totalCorrect: 0,
    masteredSkills: 0,
    subjectsTried: 0,
    earnedBadges: [],
  });
  const [toasts, setToasts] = useState([]);

  // Toast notification system
  const pushToast = (msg, kind = 'info') => {
    const id = Date.now() + Math.random();
    setToasts(t => [...t, { id, msg, kind }]);
    setTimeout(() => setToasts(t => t.filter(x => x.id !== id)), 3500);
  };

  // Record answer and update stats
  const recordAnswer = (skillId, questionId, correct, difficulty) => {
    setProgress(prev => {
      const sp = prev[skillId] || { attempts: 0, correct: 0, history: [], asked: [] };
      return {
        ...prev,
        [skillId]: {
          attempts: sp.attempts + 1,
          correct: sp.correct + (correct ? 1 : 0),
          history: [...sp.history, correct],
          asked: sp.asked.includes(questionId) ? sp.asked : [...sp.asked, questionId],
        },
      };
    });

    setStats(prev => {
      const newRunStreak = correct ? prev.currentRunStreak + 1 : 0;
      const points = correct ? (5 + difficulty * 3) : 1;
      return {
        ...prev,
        totalAnswered: prev.totalAnswered + 1,
        totalCorrect: prev.totalCorrect + (correct ? 1 : 0),
        points: prev.points + points,
        currentRunStreak: newRunStreak,
        bestStreak: Math.max(prev.bestStreak, newRunStreak),
      };
    });
  };

  // Recalculate mastered skills and subjects tried
  useEffect(() => {
    const masteredCount = Object.entries(progress)
      .filter(([id, p]) => calcMastery(p) >= 85).length;
    const subjects = new Set(
      Object.keys(progress)
        .map(id => SKILLS[id]?.subject)
        .filter(Boolean)
    );
    setStats(prev => {
      if (prev.masteredSkills === masteredCount && prev.subjectsTried === subjects.size) return prev;
      return { ...prev, masteredSkills: masteredCount, subjectsTried: subjects.size };
    });
  }, [progress]);

  // Award badges
  useEffect(() => {
    const newlyEarned = BADGES.filter(b => b.check(stats) && !stats.earnedBadges.includes(b.id));
    if (newlyEarned.length) {
      setStats(prev => ({ ...prev, earnedBadges: [...prev.earnedBadges, ...newlyEarned.map(b => b.id)] }));
      newlyEarned.forEach(b => pushToast(`🏅 Badge unlocked: ${b.name}!`, 'success'));
    }
  }, [stats.points, stats.streak, stats.bestStreak, stats.totalAnswered, stats.masteredSkills, stats.subjectsTried]);

  // Navigation handlers
  const goHome = () => {
    setView('home');
    setSelectedGrade(null);
    setSelectedSubject(null);
    setActiveSkill(null);
  };

  const handleLogin = (name, role) => {
    setUser({ name: name || 'Learner', role: role || 'student' });
    setView('home');
    pushToast(`Welcome, ${name || 'Learner'}! 🎉`, 'success');
  };

  const handleLogout = () => {
    setUser(null);
    setProgress({});
    setStats({
      points: 0,
      streak: 1,
      bestStreak: 0,
      currentRunStreak: 0,
      totalAnswered: 0,
      totalCorrect: 0,
      masteredSkills: 0,
      subjectsTried: 0,
      earnedBadges: [],
    });
    setView('login');
  };

  return (
    <div style={baseStyles.app}>
      <style>{globalStyles}</style>

      {view !== 'login' && (
        <Header
          user={user}
          stats={stats}
          onHome={goHome}
          onDashboard={() => setView('dashboard')}
          onBadges={() => setView('badges')}
          onLogout={handleLogout}
        />
      )}

      <main style={baseStyles.main}>
        {view === 'login' && <LoginScreen onLogin={handleLogin} />}
        {/* Implement other screens here - see directory structure for components */}
        {view !== 'login' && view !== 'dashboard' && view !== 'badges' && (
          <div style={baseStyles.container}>
            <div style={{ textAlign: 'center', padding: '60px 24px' }}>
              <h2>More screens coming soon!</h2>
              <p>Check the components/screens directory to add:</p>
              <ul style={{ textAlign: 'left', maxWidth: 400, margin: '0 auto' }}>
                <li>HomeScreen</li>
                <li>GradeScreen</li>
                <li>SubjectScreen</li>
                <li>SkillScreen</li>
                <li>Dashboard</li>
                <li>BadgesScreen</li>
              </ul>
            </div>
          </div>
        )}
      </main>

      {/* Toasts */}
      <div style={{ position: 'fixed', bottom: 24, right: 24, zIndex: 9999, display: 'flex', flexDirection: 'column', gap: 12 }}>
        {toasts.map(t => (
          <div
            key={t.id}
            style={{
              padding: '12px 16px',
              borderRadius: 8,
              color: 'white',
              background: t.kind === 'success' ? '#7DCE82' : t.kind === 'error' ? '#FF6B6B' : '#3DB2FF',
              fontSize: 14,
              fontWeight: 600,
            }}
          >
            {t.msg}
          </div>
        ))}
      </div>

      {view !== 'login' && <Footer />}
    </div>
  );
}
